  var testPayload = {
  "eyebrow": "Grammar & Style · Unit 3: Clarity",
  "title": "Misconception Check: the dangling modifier",
  "prompt": "Walking through the lab doors, the fume hood hummed overhead.",
  "sourceNote": "Draft sentence from Lab Report 2 — Methods section (peer-review round)",
  "popularFix": {
    "label": "The popular fix",
    "text": "Insert an adverb: \"Walking through the lab doors, the fume hood loudly hummed overhead.\"",
    "believable": "It sounds more descriptive, so it feels like an upgrade — and it hides the fact that no one is walking."
  },
  "choices": [
    {
      "id": "adv",
      "text": "Add an intensifier to the verb: \"...the fume hood loudly hummed overhead.\"",
      "correct": false,
      "why": "Adding an adverb dresses up the verb, but the opening phrase still has no subject to attach to — the hood is still doing the walking."
    },
    {
      "id": "agent",
      "text": "Name the walker: \"Walking through the lab doors, I heard the fume hood humming overhead.\"",
      "correct": true,
      "why": "The participial phrase now attaches to \"I,\" the actual agent of the walking, and the hood becomes the object of the main clause."
    },
    {
      "id": "participle",
      "text": "Convert the opener into a time clause: \"As I walked through the lab doors, the fume hood hummed overhead.\"",
      "correct": true,
      "why": "A finite clause with its own subject (\"As I walked...\") can't dangle — it names the walker outright."
    },
    {
      "id": "delete",
      "text": "Delete the comma after \"doors.\"",
      "correct": false,
      "why": "Introductory participial phrases take a comma; removing it only creates a punctuation error on top of the dangling modifier."
    }
  ],
  "misconception": {
    "title": "Why dangling modifiers feel like a style problem, not a grammar one",
    "feelsRight": "The sentence is vivid, rhythmic and ungrammatical in a way that doesn't sound 'wrong' out loud — English lets participial openers float, so the ear rarely flags them. Writers assume that if the intended subject appears anywhere nearby (the writer is obviously the one walking), the reader will supply it.",
    "whyItFails": "Readers do parse the subject grammatically, not mentally. The noun closest to \"Walking\" becomes the walker, so the sentence claims the fume hood walked through the doors. Adding an adverb makes the wrong reading sound even more confident."
  },
  "fix": {
    "title": "The actual repair",
    "explanation": "Either name the agent in the main clause (\"I heard...\") or give the opening action its own subject in a full clause (\"As I walked...\"). Both put a human walker next to the verb 'walking'.",
    "rule": "A participial phrase must share its subject with the main clause — read the opener straight into the subject of the next clause; if it produces nonsense, it's dangling.",
    "counterExample": "Compare: \"Walking through the lab doors, the fume hood hummed.\" (the hood walks) vs. \"Walking through the lab doors, I heard the hood hum.\" (I walk). One comma, one subject — same error family as \"Running late, the bus was missed.\""
  },
  "retry": {
    "label": "Pick another correction",
    "allowed": true
  },
  "doneLabel": "Continue to sentence surgery",
  "next": {
    "blockType": "Sentence_Surgery",
    "payload": {
      "focus": "participial openers",
      "items": 3
    }
  },
  "onNext": "Sentence_Surgery"
};

